/* ClearSight V2.2 Forms studio. Synthetic local fixtures only; never executes SQL,
   HTTP requests, credentials or supplied expressions. Check execution in production
   belongs in the existing scoped monitoring service, not in this form renderer. */
'use strict';
const FA_TYPES = {text:'Short text',paragraph:'Long text',number:'Number',currency:'Currency',percentage:'Percentage',date:'Date',single:'Single choice',multi:'Multiple choice',dropdown:'Dropdown / combo',boolean:'Yes / No',matrix:'Single-choice grid',multi_matrix:'Multiple-choice grid',combo_grid:'Mixed-type grid',repeat:'Repeating table',evidence:'Evidence reference',attestation:'Attestation',calculated:'Calculated value'};
const FA_CHECKS = {
 uptime:{label:'API availability over a window',slot:'observability',connector:'CON-MON',endpoint:'/metrics/payments/availability',path:'good / valid × 100',type:'percentage',unit:'%',operator:'gt',threshold:'90',window:'30 days',freshness:900,minCoverage:95,cadence:'Every 5 minutes',minSamples:100,assurance:'Measured',claim:'Observed probe availability, not proof of every customer journey.'},
 latency:{label:'HTTP response duration',slot:'web-probe',connector:'CON-WEB',endpoint:'https://bank.example/status',path:'p95(total_duration_ms)',type:'number',unit:'ms',operator:'lt',threshold:'5000',window:'24 hours',freshness:900,minCoverage:95,cadence:'Every 5 minutes',minSamples:10,assurance:'Measured',claim:'Total HTTP transaction duration from the named probe; not browser page load.'},
 api:{label:'Authenticated API response field',slot:'payment-api',connector:'CON-API',endpoint:'/v1/security/capabilities',path:'$.capabilities.idempotency',type:'boolean',unit:'',operator:'eq',threshold:'true',window:'Point in time',freshness:3600,minCoverage:100,cadence:'Hourly',minSamples:1,assurance:'Reported configuration',claim:'A capability flag reports configuration; it does not test the capability end to end.'},
 length:{label:'Database storage-length heuristic',slot:'bank-db',connector:'CON-DB',endpoint:'approved:column_octet_length_summary_v1',path:'$.minimum_octets',type:'number',unit:'bytes',operator:'gt',threshold:'32',window:'Point in time',freshness:86400,minCoverage:100,cadence:'Daily',minSamples:1,assurance:'Heuristic only',claim:'Length alone cannot establish encryption, cipher choice or strength. A long plaintext also passes.'},
 encryption:{label:'Database encryption metadata',slot:'bank-db',connector:'CON-DB',endpoint:'approved:column_encryption_metadata_v1',path:'$.encryption_algorithm_name',type:'text',unit:'',operator:'eq',threshold:'AEAD_AES_256_CBC_HMAC_SHA_512',window:'Point in time',freshness:86400,minCoverage:100,cadence:'Daily',minSamples:1,assurance:'Reported configuration',claim:'SQL Server Always Encrypted metadata for the named column. Not proof of every data copy or the whole key lifecycle.'}
};
const FA_CONNECTORS = [
 {id:'CON-MON',slot:'observability',name:'Meridian observability · read-only',credential:'vault://meridian/monitoring-read',runner:'Bank private runner · Lagos',auth:'Service identity'},
 {id:'CON-WEB',slot:'web-probe',name:'Approved public HTTP probe',credential:'No credential',runner:'Approved public probe · Lagos',auth:'None'},
 {id:'CON-API',slot:'payment-api',name:'Payments management API · read-only',credential:'vault://meridian/payments-oauth',runner:'Bank private runner · Lagos',auth:'OAuth2 client credentials'},
 {id:'CON-DB',slot:'bank-db',name:'Core banking metadata replica',credential:'vault://meridian/db-metadata-ro',runner:'Bank private runner · Lagos',auth:'Read-only database role'}
];
function faCheck(kind){return {kind,...clone(FA_CHECKS[kind])};}
function faField(id,label,type='text',extra={}){return {id,label,type,required:true,help:'',mode:'human',options:['Effective','Partially effective','Ineffective','Not applicable'],mapping:[],freshDays:90,...extra};}
function faSeeds(){return [
 {id:'FORM-OPS',name:'Branch control self-assessment',mode:'Human',framework:'FW-BANK',description:'A structured control assessment with choice grids, mixed cells, supporting evidence and accountable sign-off.',revision:2,status:'Published',fields:[
 faField('branch','Branch or operating unit','dropdown',{options:['Head Office','Ikeja','Enugu']}),
 faField('period','Assessment date','date'),
 faField('controls','Control operating effectiveness','matrix',{rows:['Daily cash reconciliation','Dual approval of payments','User access review'],options:['Effective','Partially effective','Ineffective','Not applicable']}),
 faField('channels','Evidence available for each control','multi_matrix',{rows:['Cash reconciliation','Payment authorization','User access'],options:['Policy','System log','Sample testing','Walkthrough'],help:'Select all available evidence types for each row.'}),
 faField('register','Risk and control assessment grid','combo_grid',{help:'Different types per column. Residual score is calculated, not entered.',columns:[{id:'control',label:'Control / risk',type:'text'},{id:'design',label:'Design',type:'dropdown',options:['Effective','Partial','Ineffective']},{id:'tests',label:'Test methods',type:'multi',options:['Sample','Walkthrough','System log']},{id:'likelihood',label:'Likelihood',type:'number',min:1,max:5},{id:'impact',label:'Impact',type:'number',min:1,max:5},{id:'score',label:'Residual score',type:'calculated',formula:['likelihood','impact']},{id:'evidence',label:'Evidence reference',type:'text'}],rows:[{id:'cash',label:'Cash reconciliation'},{id:'payments',label:'Payment authorization'}]}),
 faField('mfa','Is multi-factor authentication enforced for all privileged accounts?','boolean',{mapping:['R03'],freshDays:30}),
 faField('access_review','Date of the latest privileged-access review','date',{mapping:['R03','R04'],freshDays:30}),
 faField('access_evidence','Privileged-access review evidence','evidence',{mapping:['R03','R04'],freshDays:30,help:'Attach the reviewed access population and supporting control evidence.'}),
 faField('exceptions','Are there unresolved exceptions?','boolean'),
 faField('exception_note','Explain unresolved exceptions','paragraph',{condition:{field:'exceptions',equals:'Yes'},help:'Only shown when unresolved exceptions are reported.'}),
 faField('actions','Remediation action register','repeat',{required:false,columns:[{id:'action',label:'Action',type:'text'},{id:'owner',label:'Owner',type:'text'},{id:'due',label:'Due date',type:'date'}],rows:[{id:'action1',label:'Action 1'}]}),
 faField('signoff','I confirm these answers reflect the scoped assessment','attestation')
 ]},
 {id:'FORM-TECH',name:'Technical control verification',mode:'Integration',framework:'FW-BANK',description:'Source-backed fields for uptime, response time, API capabilities and database controls. Every result retains its source and rule.',revision:2,status:'Published',fields:[
 faField('availability','Payments API availability','percentage',{mode:'integration',check:faCheck('uptime')}),
 faField('response_time','Website response time','number',{mode:'integration',check:faCheck('latency')}),
 faField('capability','API reports idempotency support','boolean',{mode:'integration',check:faCheck('api')}),
 faField('storage_length','Protected column storage-length check','number',{mode:'integration',check:faCheck('length'),mapping:['R05'],mappingCoverage:'supporting'}),
 faField('crypto_metadata','Configured column encryption algorithm','text',{mode:'integration',check:faCheck('encryption'),mapping:['R05'],mappingCoverage:'supporting'})
 ]},
 {id:'FORM-VENDOR',name:'Outsourced service assurance',mode:'Hybrid',framework:'FW-VENDOR',description:'Combine vendor declarations, repeating service grids and measured technical results in one governed assessment.',revision:2,status:'Published',fields:[
 faField('contact','Accountable vendor contact','text'),
 faField('data_classes','Data categories handled','multi',{options:['Customer identifiers','Payment data','Employee data','No personal data']}),
 faField('service_grid','Service-by-service assurance','combo_grid',{help:'Respondents enter ownership and actions. Technical cells come from scoped check observations.',columns:[{id:'service',label:'Service',type:'text'},{id:'owner',label:'Owner',type:'text'},{id:'uptime',label:'Availability',type:'percentage',mode:'integration',check:faCheck('uptime')},{id:'latency',label:'Response p95',type:'number',mode:'integration',check:faCheck('latency')},{id:'action',label:'Remediation',type:'text'}],rows:[{id:'hosting',label:'Core banking hosting'},{id:'payments',label:'Payment gateway'}],mapping:['R07'],mappingCoverage:'supporting'}),
 faField('incident','Material service interruption this quarter?','boolean'),
 faField('incident_note','Incident and recovery summary','paragraph',{condition:{field:'incident',equals:'Yes'}}),
 faField('report','Independent assurance report reference','evidence',{help:'Attach a version from Documents; its original file stays linked to this submission.'}),
 faField('attest','I attest that this response covers the named engagement','attestation')
 ]}
];}
function faInit(){
 if(!S.formStudio){const forms=faSeeds();S.formStudio={forms,versions:forms.map(f=>({id:f.id+'@'+f.revision,formId:f.id,number:f.revision,definition:clone(f),published:'2026-11-13T09:00:00Z'})),bindings:[],responses:{},runs:[]};}
 return S.formStudio;
}
function faForm(){return faInit().forms.find(f=>f.id===current.params.get('form'))||faInit().forms[0];}
function faFieldSelected(f){return f.fields.find(x=>x.id===current.params.get('field'))||f.fields[0];}
function faLatest(f){return faInit().versions.filter(v=>v.formId===f.id).at(-1);}
function faEdited(f){if(f.status==='Published'){f.status='Draft';f.revision=(faLatest(f)?.number||0)+1;}save();}
function faVersion(id){return faInit().versions.find(v=>v.id===id);}
function faBinding(){return faInit().bindings.find(b=>b.id===current.params.get('binding'));}
function faResponseKey(){const b=faBinding();return b?b.id:faForm().id+'::preview';}
function faResponse(){const key=faResponseKey();return faInit().responses[key]||(faInit().responses[key]={answers:{},observations:{},status:'Draft',runIds:[]});}
function faDefinition(){const b=faBinding();return b?faVersion(b.formVersionId).definition:faForm();}
function faChecks(def,answers={}){const result=[];for(const f of def.fields){if(!faVisible(f,answers))continue;if(f.mode==='integration'&&f.check)result.push({key:f.id,label:f.label,field:f,check:f.check,target:''});if(f.columns){const rows=answers[f.id]||f.rows;for(const row of rows)for(const c of f.columns)if(c.mode==='integration'&&c.check)result.push({key:[f.id,row.id,c.id].join('::'),label:f.label+' / '+row.label+' / '+c.label,field:f,check:c.check,target:row.id});}}return result;}
function faSlots(def){return [...new Set(faChecks(def).map(x=>x.check.slot))];}
function faStatus(s){return pill(s,{Pass:'green',Fail:'red',Unknown:'amber','Not run':'',Submitted:'blue',Fresh:'green',Stale:'amber',Complete:'green',Insufficient:'amber',Unavailable:'red','Heuristic only':'amber'}[s]||'');}
function faVisible(field,answers){if(!field.condition)return true;const val=answers[field.condition.field];return Array.isArray(val)?val.includes(field.condition.equals):String(val??'')===field.condition.equals;}
function faRuleText(c){return `${c.path} ${ {eq:'=',gt:'>',gte:'≥',lt:'<',lte:'≤',contains:'contains',exists:'exists'}[c.operator]||c.operator} ${c.operator==='exists'?'':c.threshold} ${c.unit||''}`.trim();}
function faRunResult(observation){return observation?faStatus(observation.result):faStatus('Not run');}
function faValue(v){return v===null||v===undefined?'—':Array.isArray(v)?e(v.join(', ')):typeof v==='number'?Number(v.toFixed(3)).toLocaleString('en-GB'):e(String(v));}
function faNav(active){return tabLinks([['Form library','forms','library'],['Integration assessments','forms?tab=integration','integration'],['Published assignments','forms?tab=assignments','assignments'],['Check history','check-runs','runs'],['Seed question library','forms?tab=questions','questions']],active);}
const faOldFormsView=formsView;
formsView=function(){faInit();const tab=current.params.get('tab')||'library';if(tab==='questions')return faNav(tab)+faOldFormsView();const all=S.formStudio.forms,forms=tab==='integration'?all.filter(f=>f.mode!=='Human'):all;let content='';
 if(tab==='assignments')content=panel('Version-pinned assessment assignments','Each assignment belongs to a program and exact target. Changing a template does not rewrite existing assignments.',S.formStudio.bindings.length?table(['Form & version','Program / target','Sources','Status',''],S.formStudio.bindings.map(b=>({cells:[`<strong>${e(faVersion(b.formVersionId).definition.name)}</strong><small>${e(b.formVersionId)}</small>`,`<strong>${e(S.programs.find(p=>p.id===b.programId)?.name)}</strong><small>${e(targetName(b.target))}</small>`,`${Object.values(b.connections).filter(Boolean).length} / ${faSlots(faVersion(b.formVersionId).definition).length} bound`,pill(S.formStudio.responses[b.id]?.status||'Draft'),link('Open assessment','form-response?binding='+b.id,'small')]}))):empty('No forms attached yet','Publish a form, then attach the exact version to a program and target.'));
 else content=`<div class="fa-cards">${forms.map(f=>{const cs=faChecks(f);return `<article class="panel fa-card" data-search="${e(f.name+' '+f.mode)}"><div class="fa-card-top"><span class="fa-source-icon">${icon(f.mode==='Integration'?'refresh':f.mode==='Hybrid'?'layers':'form')}</span>${pill(f.mode,f.mode==='Human'?'blue':f.mode==='Hybrid'?'violet':'green')}</div><div class="fa-card-body"><div class="fa-identity">${e(f.framework?fw(f.framework).name:'Custom instrument')}</div><h2>${e(f.name)}</h2><p>${e(f.description)}</p><div class="fa-meta"><span>${f.fields.length} fields</span><span>${cs.length} technical checks</span><span>v${f.revision} · ${e(f.status)}</span></div></div><div class="fa-card-foot">${link('Open builder','form-builder?form='+f.id,'primary small')}${link('Preview','form-response?form='+f.id,'small')}${btn('Attach','fa-attach',`data-id="${f.id}"`,'quiet small')}</div></article>`;}).join('')}</div>`;
 return header('Forms & Assessments','Design questionnaires, banking grids and source-backed technical assessments.',btn(icon('plus')+' Create form','fa-create','','primary'),'Assessment studio')+faNav(tab)+(tab!=='assignments'?`<div class="fa-banner"><span class="fa-source-icon">${icon('layers')}</span><div><div class="fa-tagline">One engine. Three starting points.</div><h2>Human input. Live-source fields. Or both.</h2><p>Choose the field’s shape separately from where its value comes from. Seed forms with a framework or attach a published version to an existing program.</p></div></div>`+metricRow([metric('Reusable forms',all.length,'Versioned definitions, not copied obligations','form'),metric('Field types',Object.keys(FA_TYPES).length,'Including choice grids and mixed-column tables','layers'),metric('Technical check recipes',Object.keys(FA_CHECKS).length,'Synthetic, inspectable source fixtures','refresh'),metric('Assignments',S.formStudio.bindings.length,'Pinned to program, target and form version','program')])+tools('Search forms'):notice('An assignment creates a scoped response set. It does not add regulatory obligations or establish requirement satisfaction.'))+content+noMatch;
};
function formBuilderView(){const f=faForm(),q=faFieldSelected(f),tab=current.params.get('inspector')||'field';return header(e(f.name),`v${f.revision} ${f.status.toLowerCase()} · ${f.mode} assessment · ${f.fields.length} fields`,link('Respondent preview',`form-response?form=${f.id}`)+' '+btn('Publish version','fa-publish',`data-id="${f.id}"`,'primary'),'Form builder',`<a href="#/forms">Forms</a>${icon('chevron')}Builder`)+`<div class="fa-controlbar">${pill(f.mode,'blue')}${pill(f.status)}<span class="small muted grow">Source definitions, checks and responses remain separate.</span>${btn('Form settings','fa-settings',`data-id="${f.id}"`,'small')}${btn('Export schema','fa-export',`data-id="${f.id}"`,'small')}</div><div class="fa-builder"><aside class="panel fa-outline"><div class="panel-head"><h2>Form outline</h2><span class="small muted">${f.fields.length}</span></div>${f.fields.map((x,i)=>`<button class="fa-outline-row ${q?.id===x.id?'active':''}" data-action="fa-select" data-id="${x.id}"><span class="fa-outline-number">${String(i+1).padStart(2,'0')}</span><span>${e(x.label)}<small>${e(FA_TYPES[x.type])} · ${e(x.mode)}</small></span></button>`).join('')}<div class="fa-add">${btn(icon('plus')+' Add field','fa-add','','small wide')}</div></aside><section class="fa-canvas"><div class="panel fa-form-head"><div class="fa-tagline">${e(f.mode)} assessment</div><h2>${e(f.name)}</h2><p>${e(f.description)}</p></div>${f.fields.map((x,i)=>faRenderField(x,{}, {},true,q?.id===x.id,i)).join('')}</section><aside class="panel fa-inspector"><div class="fa-inspector-tabs">${['field','source','rules'].map(t=>`<button type="button" class="${t===tab?'active':''}" data-action="fa-inspector" data-id="${t}">${{field:'Field',source:'Data source',rules:'Rules & logic'}[t]}</button>`).join('')}</div><div class="pad">${q?faInspector(f,q,tab):'<p>Add a field to begin.</p>'}</div></aside></div>`;}
function faInspector(f,q,tab){let body='';
 if(tab==='field')body=input('label','Field label',q.label,'text','required maxlength="180"')+select('type','Display / answer type',Object.entries(FA_TYPES),q.type)+area('help','Guidance',q.help,'maxlength="1500"')+select('required','Required',[['yes','Required'],['no','Optional']],q.required?'yes':'no')+(['single','multi','dropdown','matrix','multi_matrix'].includes(q.type)?area('options','Options (one per line)',q.options.join('\n'),'required'):'')+(['matrix','multi_matrix'].includes(q.type)?area('rows','Row labels (one per line)',q.rows.join('\n'),'required'):'')+(q.columns?`<div class="fa-subtle">${q.columns.length} typed columns. Each technical column has its own source and rule; calculated columns use stable column IDs.</div>${btn('Edit columns','fa-columns',`data-id="${q.id}"`,'small')}`:'');
 if(tab==='source')body=select('mode','Value comes from',[['human','Respondent'],['integration','Integration / source'],['calculated','Calculation']],q.mode)+(q.mode==='integration'?select('checkKind','Check recipe',Object.entries(FA_CHECKS).map(([id,x])=>[id,x.label]),q.check?.kind||'api')+`<div class="fa-subtle">${e(q.check?.claim||'Choose an approved recipe.')}</div>`+input('endpoint','Approved endpoint / query reference',q.check?.endpoint||'','text','required')+input('path','Extract / aggregate',q.check?.path||'','text','required')+`<div class="source-block"><strong class="small">${e(q.check?.slot||'payment-api')}</strong><p class="fa-subtle mb0">Logical connector slot. Actual connection, runner and vault credential reference are bound per program target, never embedded in the framework.</p></div>`:q.mode==='calculated'?select('calcOp','Calculation',[['sum','Sum'],['product','Product'],['average','Average']],q.calcOp||'product')+area('depends','Numeric field IDs (one per line)',(q.depends||[]).join('\n'),'required')+notice('Restricted typed calculations only. No JavaScript, SQL or eval expressions.','mini'):notice(q.columns?'Grid columns may still be integration-backed or calculated. Edit columns to configure their sources.':'This field is answered by the assigned respondent.','mini'));
 if(tab==='rules')body=area('mapping','Requirement IDs (one per line)',q.mapping.join('\n'),'placeholder="R03"')+input('freshDays','Human answer freshness (days)',q.freshDays,'number','min="1" max="3650" required')+(q.mode==='integration'?select('operator','Check operator',[['gt','Greater than'],['gte','At least'],['lt','Less than'],['lte','At most'],['eq','Equals'],['contains','Contains'],['exists','Exists']],q.check.operator)+input('threshold','Expected / threshold',q.check.threshold,'text')+select('window','Observation window',['Point in time','24 hours','30 days'],q.check.window)+input('freshness','Source freshness limit (seconds)',q.check.freshness,'number','required min="1" max="31536000"')+input('minCoverage','Minimum collection coverage (%)',q.check.minCoverage,'number','required min="0" max="100" step="0.1"')+input('minSamples','Minimum valid samples',q.check.minSamples,'number','required min="1" max="1000000"')+select('cadence','Schedule policy',['Every 5 minutes','Hourly','Daily','On demand'],q.check.cadence):'')+select('showWhen','Show only when (optional)',[['','Always visible'],...f.fields.filter(x=>x.id!==q.id&&['single','dropdown','boolean','multi'].includes(x.type)).map(x=>[x.id,x.label])],q.condition?.field||'')+input('equals','Required value for visibility',q.condition?.equals||'')+notice('Missing, invalid, stale or insufficient source data cannot become Pass. A check result does not automatically satisfy mapped requirements.','mini');
 return `<div class="fa-splitline"><strong>${e(q.id)}</strong><span>Stable field ID</span></div><form id="fa-field-settings" data-fa-settings="${e(tab)}">${body}<div class="fa-form-error" role="alert"></div><button class="btn primary wide" type="submit">Apply changes</button></form><hr class="divider"><div class="row wrap">${btn('Move up','fa-move',`data-id="${q.id}" data-direction="-1"`,'small')}${btn('Move down','fa-move',`data-id="${q.id}" data-direction="1"`,'small')}${btn('Remove','fa-remove',`data-id="${q.id}"`,'small danger')}</div>`;
}
function faCalc(op,values){if(!values.length||values.some(v=>v===''||v===null||v===undefined||typeof v==='boolean'||!Number.isFinite(Number(v))))return null;const ns=values.map(Number);return op==='product'?ns.reduce((a,b)=>a*b,1):op==='average'?ns.reduce((a,b)=>a+b,0)/ns.length:ns.reduce((a,b)=>a+b,0);}
function faCalcField(f,answers){return faCalc(f.calcOp||'product',(f.depends||[]).map(id=>answers[id]));}
function faBasicControl(type,value,attr,optionsList=[],disabled=false){const lock=disabled?'disabled':'';const val=e(value??'');
 if(type==='paragraph')return `<textarea ${attr} ${lock} placeholder="Enter a meaningful response">${val}</textarea>`;
 if(type==='single'||type==='boolean')return `<div class="fa-choices">${(type==='boolean'?['Yes','No']:optionsList).map(o=>`<label class="fa-choice"><input type="radio" ${attr} value="${e(o)}" ${value===o?'checked':''} ${lock}>${e(o)}</label>`).join('')}</div>`;
 if(type==='multi')return `<div class="fa-choices">${optionsList.map(o=>`<label class="fa-choice"><input type="checkbox" ${attr} value="${e(o)}" ${(value||[]).includes(o)?'checked':''} ${lock}>${e(o)}</label>`).join('')}</div>`;
 if(type==='dropdown')return `<select ${attr} ${lock}>${options([['','Select an option'],...optionsList],value||'')}</select>`;
 if(type==='attestation')return `<label class="fa-choice"><input type="checkbox" ${attr} ${value===true?'checked':''} ${lock}>Confirmed by the submitting respondent</label>`;
 if(type==='currency')return `<div class="row"><span class="badge">NGN</span><input type="number" ${attr} value="${val}" min="0" step="0.01" ${lock} placeholder="0.00"></div>`;
 if(type==='evidence')return `<input type="text" ${attr} value="${val}" ${lock} placeholder="Evidence record ID or controlled document reference"><p class="fa-subtle mt16 mb0">Metadata only in this demo. A reference is not evidence acceptance.</p>`;
 return `<input type="${type==='date'?'date':['number','percentage'].includes(type)?'number':'text'}" ${attr} value="${val}" ${type==='percentage'?'min="0" max="100" step="0.01"':type==='number'?'step="any"':''} ${lock} placeholder="${type==='percentage'?'0–100':'Enter response'}">`;
}
function faRenderGrid(q,answers,observations,builder,locked){const rows=answers[q.id]||q.rows.map(r=>({...r,cells:{}}));return `<div class="fa-grid-scroll" tabindex="0" aria-label="${e(q.label)} scrollable grid"><table class="fa-grid"><thead><tr>${q.columns.map(c=>`<th scope="col">${e(c.label)}${c.mode==='integration'?'<small class="fa-subtle"><br>Source-backed</small>':c.type==='calculated'?'<small class="fa-subtle"><br>Calculated</small>':''}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${q.columns.map(c=>{let content='';const val=row.cells?.[c.id]??'';const attr=`data-fa-cell="${q.id}" data-row="${e(row.id)}" data-col="${e(c.id)}" aria-label="${e(row.label+' — '+c.label)}"`;if(c.mode==='integration'){const ob=observations[[q.id,row.id,c.id].join('::')];content=`<div class="fa-cell-source"><span>${ob?faValue(ob.value):'—'} ${ob?e(c.check.unit):''}</span>${faRunResult(ob)}</div>`;}else if(c.type==='calculated')content=`<output class="fa-score" aria-label="${e(row.label+' — '+c.label)}">${faValue(faCalc('product',(c.formula||[]).map(id=>row.cells?.[id])))}</output>`;else if(c.type==='multi')content=`<select multiple ${attr} ${builder||locked?'disabled':''}>${c.options.map(o=>`<option value="${e(o)}" ${(val||[]).includes(o)?'selected':''}>${e(o)}</option>`).join('')}</select>`;else content=faBasicControl(c.type,val,attr+(c.type==='number'?` min="${c.min??0}" max="${c.max??1000000000}"`:''),c.options||[],builder||locked);return `<td class="${c.type==='multi'?'fa-multi-cell':''}">${content}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${!builder&&!locked?`<div class="fa-grid-controls">${btn('Add row','fa-add-row',`data-id="${q.id}"`,'small')}${rows.length>1?btn('Remove last row','fa-remove-row',`data-id="${q.id}"`,'quiet small'):''}${!q.columns.some(c=>c.mode==='integration')?btn('Paste table (TSV)','fa-paste',`data-id="${q.id}"`,'quiet small'):''}</div>`:''}`;}
function faRenderField(q,answers={},observations={},builder=false,selected=false,index=0,locked=false){let body='';const val=answers[q.id];const a=`data-fa-answer="${q.id}" name="fa-${q.id}" aria-label="${e(q.label)}"`;const ob=observations[q.id];
 if(q.mode==='integration'){body=`<div class="fa-technical-value"><div><strong>${faValue(ob?.value)}</strong><span class="fa-unit">${ob?e(q.check.unit):''}</span></div>${faRunResult(ob)}</div><div class="fa-ruleline">${e(faRuleText(q.check))}</div><div class="fa-provenance"><span>${e(q.check.slot)}</span><span>${e(q.check.window)}</span><span>${e(q.check.assurance)}</span></div>${ob?`<div class="fa-provenance"><span>Execution: ${e(ob.execution)}</span><span>Quality: ${e(ob.quality)}</span><span>Coverage: ${ob.coverage}%</span><span>${e(ob.reason)}</span></div>`:''}${q.check.kind==='length'?notice('Heuristic only. Passing a length rule does not prove encryption or identify 3DES.','mini warning'):''}`;
 }else if(q.mode==='calculated'||q.type==='calculated')body=`<div class="fa-technical-value"><output><strong>${faValue(faCalcField(q,answers))}</strong></output>${pill('Calculated','blue')}</div><p class="fa-subtle mt16">${e(q.calcOp||'product')} of ${(q.depends||[]).map(e).join(', ')||'configured numeric fields'}</p>`;
 else if(['matrix','multi_matrix'].includes(q.type))body=`<div class="fa-grid-scroll" tabindex="0"><table class="fa-grid"><thead><tr><th scope="col">Assessment item</th>${q.options.map(o=>`<th scope="col" class="fa-matrix-cell">${e(o)}</th>`).join('')}</tr></thead><tbody>${q.rows.map((row,ri)=>`<tr><th scope="row">${e(row)}</th>${q.options.map(o=>`<td class="fa-matrix-cell"><input type="${q.type==='matrix'?'radio':'checkbox'}" name="${q.id}-${ri}" value="${e(o)}" data-fa-matrix="${q.id}" data-row="${ri}" aria-label="${e(row+' — '+o)}" ${(q.type==='matrix'?val?.[ri]===o:(val?.[ri]||[]).includes(o))?'checked':''} ${builder||locked?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 else if(q.columns)body=faRenderGrid(q,answers,observations,builder,locked);
 else body=faBasicControl(q.type,val,a,q.options,builder||locked);
 return `<article class="fa-field ${selected?'fa-selected':''}" id="fa-field-${q.id}"><div class="fa-field-title"><div><span class="faint mono">${String(index+1).padStart(2,'0')} · ${e(q.id)}${q.mapping.length?' · '+q.mapping.map(e).join(' / '):''}</span><h3>${e(q.label)}${q.required?' <span class="fa-required" aria-label="required">*</span>':''}</h3></div>${builder?btn('Configure','fa-select',`data-id="${q.id}"`,'quiet small'):pill(q.mode==='integration'?'Source-backed':q.mode==='calculated'?'Calculated':'Respondent',q.mode==='integration'?'blue':'')}</div>${q.help?`<p class="fa-help">${e(q.help)}</p>`:''}${q.condition?`<p class="fa-subtle">Shown when ${e(q.condition.field)} = ${e(q.condition.equals)}</p>`:''}${body}</article>`;
}
function faErrors(def,res){const errors=[];for(const f of def.fields){if(!faVisible(f,res.answers))continue;const v=res.answers[f.id];if(f.mode==='integration')continue;
 if(f.mode==='calculated'||f.type==='calculated'){if(f.required&&faCalcField(f,res.answers)===null)errors.push(f.label+': calculation has missing inputs.');continue;}
 if(f.columns){const rows=v||f.rows.map(r=>({...r,cells:{}}));if(!f.required&&rows.every(r=>Object.values(r.cells||{}).every(x=>!String(x).trim())))continue;for(const row of rows)for(const c of f.columns){if(c.mode==='integration'||c.type==='calculated')continue;const cell=row.cells?.[c.id];if(c.required!==false&&(cell==null||cell===''||(Array.isArray(cell)&&!cell.length)))errors.push(f.label+' / '+row.label+' / '+c.label+': required.');if(c.type==='number'&&cell!==undefined&&cell!==''&&(!Number.isFinite(Number(cell))||Number(cell)<(c.min??-Infinity)||Number(cell)>(c.max??Infinity)))errors.push(c.label+': outside the allowed numeric range.');}continue;}
 if(['matrix','multi_matrix'].includes(f.type)){if(f.required&&f.rows.some((_,i)=>f.type==='matrix'?!v?.[i]:!v?.[i]?.length))errors.push(f.label+': complete each row.');continue;}
 if(f.required&&(v===null||v===undefined||v===''||(Array.isArray(v)&&!v.length)||(f.type==='attestation'&&v!==true)))errors.push(f.label+': required.');
 if(['number','percentage','currency'].includes(f.type)&&v!==undefined&&v!==''&&(!Number.isFinite(Number(v))||(f.type==='percentage'&&(Number(v)<0||Number(v)>100))||(f.type==='currency'&&!/^\d+(\.\d{1,2})?$/.test(String(v)))))errors.push(f.label+': invalid number / precision.');
 }
 return errors;
}
function faInputCompleteness(def,res){const fields=def.fields.filter(f=>faVisible(f,res.answers));let n=0;for(const f of fields){if(f.mode==='integration'){if(res.observations[f.id])n++;}else if(!faErrors({...def,fields:[f]},res).length)n++;}return {done:n,total:fields.length};}
function formResponseView(){const def=faDefinition(),res=faResponse(),binding=faBinding(),locked=res.status==='Submitted',fields=def.fields.filter(f=>faVisible(f,res.answers)),checks=faChecks(def,res.answers),progName=binding?S.programs.find(p=>p.id===binding.programId)?.name:'Unassigned designer preview',progress=faInputCompleteness(def,res);return header(e(def.name),binding?`${progName} · ${targetName(binding.target)} · ${binding.formVersionId}`:'Respondent preview · draft answers saved separately from the form definition',link('Back to forms','forms')+(!binding?link('Edit form',`form-builder?form=${def.id}`):''),'Assessment response')+notice(locked?'Submitted snapshot is locked. Later monitoring runs appear in history without rewriting these responses.':'Technical observations are read-only. Failed checks may be submitted for review; missing or uncertain observations require an explicit explanation.')+`<div class="fa-controlbar">${pill(binding?'Program assignment':'Preview only','blue')}${pill(res.status)}<span class="grow small muted">${e(progName)}</span>${checks.length?`<select id="fa-scenario" aria-label="Technical fixture scenario" ${locked?'disabled':''}>${options([['healthy','Healthy source fixtures'],['breach','Threshold breached'],['unavailable','Collector / credential error'],['stale','Stale observations'],['sparse','Insufficient collection coverage']],res.scenario||'healthy')}</select>${btn('Run technical checks','fa-run','id="fa-run-button" '+(locked?'disabled':''),'primary')}`:''}${!locked?btn('Load example answers','fa-example','','small'):''}</div><div class="fa-response-layout"><section class="fa-canvas">${fields.map((q,i)=>faRenderField(q,res.answers,res.observations,false,false,i,locked)).join('')}${def.fields.length-fields.length?`<div class="fa-hidden-count">${def.fields.length-fields.length} conditional field(s) not currently applicable.</div>`:''}</section><aside class="fa-stack fa-side-summary">${panel('Assessment status','',`<div class="pad"><div class="cycle-count" style="margin:0">${progress.done}<span> / ${progress.total} fields</span></div><div class="progress mt16"><i style="width:${(progress.total?progress.done/progress.total*100:0)}%"></i></div><div class="fa-summary-facts mt16"><div>${checks.length} technical checks</div><div>${Object.values(res.observations).filter(o=>o.result==='Pass').length} passed · ${Object.values(res.observations).filter(o=>o.result==='Fail').length} failed · ${Object.values(res.observations).filter(o=>o.result==='Unknown').length} unknown</div><div>Requirement conclusion: <strong>Not evaluated here</strong></div></div>${!locked?`<hr class="divider"><label>Explain uncertain / unavailable checks<textarea data-fa-note placeholder="Required only when technical checks are missing, stale or unknown.">${e(res.note||'')}</textarea></label><div class="fa-form-error" id="fa-response-error" role="alert"></div>${btn('Submit for review','fa-submit','','primary wide mt16')}`:notice(`Submitted by ${e(res.submittedBy)}. Form and observations are frozen in this local run.`, 'mini mt16')}</div>`)}${panel('Assessment rules','',`<div class="pad"><div class="fa-summary-facts"><div>Source values ≠ answers supplied by people.</div><div>Check outcomes ≠ requirement conclusions.</div><div>Missing data ≠ a passing control.</div></div><hr class="divider">${link('Inspect execution history','check-runs','wide small')}${binding?link('Open program',`program?id=${binding.programId}&target=${encodeURIComponent(binding.target)}&tab=assessments`,'wide quiet small'):''}</div>`)}${notice('Demo only: no credentials are collected, no requests are sent and no database content is read.','mini')}</aside></div>`;}
/* Fixed, synthetic source observations. Query names are references, never SQL. */
function faFixture(check,scenario,target){const now=Date.now(),bad=scenario==='breach',sparse=scenario==='sparse',base={observedAt:new Date(now-(scenario==='stale'?check.freshness*1000+1000:1000)).toISOString(),expected:1,valid:1};if(scenario==='unavailable')return {...base,error:'COLLECTOR_AUTH_ERROR'};
 if(check.kind==='uptime')return {...base,expected:8640,valid:sparse?120:8540,good:sparse?120:bad?7200:8345,window:check.window};
 if(check.kind==='latency')return {...base,expected:288,valid:sparse?2:288,durations:Array.from({length:sparse?2:288},(_,i)=>(bad?[6000,6800,7200,5600,5900,8100,7400,6500,6200,7000]:[2010,2200,1950,2610,2300,2400,1890,2500,2850,3100])[i%10]),totalSamples:sparse?2:288,point:'Lagos / approved probe',window:check.window};
 if(check.kind==='api')return {...base,body:{capabilities:{idempotency:!bad,mutualTLS:true},status:'ok'}};
 if(check.kind==='length')return {...base,body:{minimum_octets:bad?16:64,rows_checked:1000,null_count:0},queryVersion:'column_octet_length_summary_v1'};
 return {...base,body:{encryption_algorithm_name:bad?'NONE':'AEAD_AES_256_CBC_HMAC_SHA_512',encryption_type_desc:'RANDOMIZED',column:'customer_identifier'},queryVersion:'column_encryption_metadata_v1'};
}
function faExtract(body,path){if(!/^\$(\.[A-Za-z_][A-Za-z_0-9]*)+$/.test(path))throw Error('Use a restricted $.property.path selector.');let val=body;for(const part of path.slice(2).split('.')){if(['__proto__','constructor','prototype'].includes(part)||!val||!Object.prototype.hasOwnProperty.call(val,part))throw Error('Response field is missing.');val=val[part];}return val;}
function faCompare(value,operator,threshold){if(operator==='exists')return value!==null&&value!==undefined;if(operator==='contains')return typeof value==='string'?value.includes(String(threshold)):Array.isArray(value)?value.includes(threshold):false;
 if(['gt','gte','lt','lte'].includes(operator)){if(typeof value!=='number'||!Number.isFinite(value)||String(threshold).trim()===''||!Number.isFinite(Number(threshold)))throw Error('Numeric rule requires a finite numeric value and threshold.');const n=Number(threshold);return {gt:()=>value>n,gte:()=>value>=n,lt:()=>value<n,lte:()=>value<=n}[operator]();}
 if(operator!=='eq')throw Error('Unsupported operator.');let expected=threshold;if(typeof value==='boolean'){if(!['true','false'].includes(String(threshold)))throw Error('Boolean expected value must be true or false.');expected=String(threshold)==='true';}else if(typeof value==='number'){if(String(threshold).trim()===''||!Number.isFinite(Number(threshold)))throw Error('Expected value is not numeric.');expected=Number(threshold);}return value===expected;
}
function faEvaluate(check,raw,now=Date.now()){const out={value:null,execution:'Succeeded',quality:'Fresh',result:'Unknown',reason:'',coverage:0,observedAt:raw.observedAt,assurance:check.assurance,rule:faRuleText(check),window:check.window,metrics:{}};
 if(raw.error){return {...out,execution:'Failed',quality:'Unavailable',reason:raw.error};}
 if(!Number.isInteger(raw.expected)||raw.expected<=0||!Number.isInteger(raw.valid)||raw.valid<0||raw.valid>raw.expected)return {...out,quality:'Invalid',reason:'Invalid collection population counts.'};
 const coverage=raw.valid/raw.expected*100;out.coverage=Math.round(coverage*100)/100;out.metrics={valid:raw.valid,expected:raw.expected};
 try{if(check.kind==='uptime'){if(check.path!=='good / valid × 100')throw Error('Availability recipe expects its approved good / valid aggregation.');if(raw.valid<=0||raw.good<0||raw.good>raw.valid)throw Error('Invalid availability numerator / denominator.');out.value=raw.good/raw.valid*100;out.metrics.good=raw.good;}else if(check.kind==='latency'){if(check.path!=='p95(total_duration_ms)')throw Error('Latency recipe expects its approved p95 aggregation.');const sorted=raw.durations.slice().sort((a,b)=>a-b);out.value=sorted[Math.ceil(.95*sorted.length)-1];out.metrics.distribution='Synthetic latency sample distribution';}else out.value=faExtract(raw.body,check.path);
 if(out.value===null||out.value===undefined||(!['number','boolean','text'].includes(check.type)&&check.type!=='percentage'))throw Error('Missing or unsupported value.');
 if(['number','percentage'].includes(check.type)&&(typeof out.value!=='number'||!Number.isFinite(out.value)))throw Error('Source type mismatch: expected number.');if(check.type==='boolean'&&typeof out.value!=='boolean')throw Error('Source type mismatch: expected boolean.');if(check.type==='text'&&typeof out.value!=='string')throw Error('Source type mismatch: expected string.');
 const ts=Date.parse(raw.observedAt);if(!Number.isFinite(ts)||ts>now+60000)throw Error('Invalid source timestamp.');
 if(now-ts>check.freshness*1000)return {...out,quality:'Stale',reason:'Last known value is stale; retained for context only.'};
 if(coverage<check.minCoverage||raw.valid<check.minSamples)return {...out,quality:'Insufficient',reason:'Insufficient valid observations / collection coverage.'};
 out.result=faCompare(out.value,check.operator,check.threshold)?'Pass':'Fail';out.reason=check.assurance==='Heuristic only'?'Rule result only; encryption remains unverified.':'Scoped check only; requirement review remains separate.';return out;
 }catch(err){return {...out,quality:'Invalid',reason:err.message};}}
function faRun(){const res=faResponse(),def=faDefinition(),binding=faBinding();requireValue(res.status!=='Submitted','Submitted snapshots cannot be overwritten.');const scenario=$('#fa-scenario')?.value||res.scenario||'healthy';res.scenario=scenario;const checks=faChecks(def,res.answers),cache=new Map(),results={};for(const item of checks){const c=item.check,conn=binding?binding.connections[c.slot]:FA_CONNECTORS.find(x=>x.slot===c.slot)?.id;let raw;if(!conn)raw={error:'UNBOUND_CONNECTION',observedAt:new Date().toISOString()};else{const key=JSON.stringify([conn,item.target,c.kind,c.endpoint,c.window,scenario]);if(!cache.has(key))cache.set(key,faFixture(c,scenario,item.target));raw=cache.get(key);}results[item.key]={...faEvaluate(c,raw),fieldId:item.field.id,checkKey:item.key,connectorId:conn||null,label:item.label,sourceReference:c.endpoint,extractor:c.path,subject:binding?.target||'Designer preview',rowTarget:item.target};}
 const run={id:uid('RUN'),time:new Date().toISOString(),formId:def.id,version:binding?.formVersionId||`${def.id}@${def.status==='Published'?'preview-v':'draft-v'}${def.revision}`,bindingId:binding?.id||null,target:binding?.target||'Designer preview',scenario,sourceReads:cache.size,definition:clone(def),results};faInit().runs.unshift(run);res.observations=clone(results);res.runIds.push(run.id);audit('Synthetic form check run '+run.id+' · '+checks.length+' observations',binding?.programId||def.id);render();toast(`Recorded ${checks.length} synthetic observations. No external calls were made.`);return run;}
function checkRunsView(){const runs=faInit().runs;return header('Technical check history','Inspect execution health, data quality and rule outcomes independently.',link('Integration forms','forms?tab=integration','primary'),'Assessment observability')+faNav('runs')+notice('All records below are synthetic. Each run stores the exact form definition, scope and check rules used. No compliance conclusions are changed.')+panel('Execution ledger','Latest runs first. A new run never erases prior observations.',runs.length?table(['Run / form version','Subject','Execution','Rule outcomes',''],runs.map(r=>{const v=Object.values(r.results);return {cells:[`<strong>${e(r.id)}</strong><small>${e(r.version)} · ${e(r.scenario)}</small>`,e(targetName(r.target)),`${v.filter(o=>o.execution==='Succeeded').length}/${v.length} collected<small>${r.sourceReads} source reads</small>`,`${faStatus('Pass')} ${v.filter(o=>o.result==='Pass').length} ${faStatus('Fail')} ${v.filter(o=>o.result==='Fail').length} ${faStatus('Unknown')} ${v.filter(o=>o.result==='Unknown').length}`,btn('Inspect','fa-run-detail',`data-id="${r.id}"`,'small')]};})):empty('No checks run yet','Open Technical control verification, then run a fixture.',link('Open technical form','form-response?form=FORM-TECH','primary')));}
function faDefaultField(type,id){const f=faField(id,FA_TYPES[type]||'New field',type,{required:false});if(['matrix','multi_matrix'].includes(type))f.rows=['Assessment item 1','Assessment item 2'];if(['combo_grid','repeat'].includes(type)){f.columns=[{id:'item',label:'Item',type:'text'},{id:'status',label:'Status',type:'dropdown',options:['Effective','Partial','Ineffective']},{id:'owner',label:'Owner',type:'text'}];f.rows=[{id:'row1',label:'Item 1'}];}if(type==='calculated'){f.mode='calculated';f.calcOp='sum';f.depends=[];}return f;}
function faActualMode(def){const hasMachine=faChecks(def).length>0,hasHuman=def.fields.some(f=>f.mode==='human'&&(f.columns?f.columns.some(c=>c.mode!=='integration'&&c.type!=='calculated'):true));return hasMachine?hasHuman?'Hybrid':'Integration':'Human';}
function faDefinitionErrors(def){const errs=[];if(!def.name.trim())errs.push('Give the form a name.');if(!def.fields.length)errs.push('Add at least one field.');const ids=new Set(def.fields.map(f=>f.id));if(ids.size!==def.fields.length)errs.push('Field IDs must be unique.');for(const f of def.fields){if(!f.label.trim())errs.push(f.id+': label is required.');if((f.depends||[]).some(id=>!ids.has(id)||id===f.id))errs.push(f.id+': invalid calculation dependency.');if(f.mode==='calculated'&&(!f.depends?.length||f.depends.some(id=>!['number','percentage','currency','calculated'].includes(def.fields.find(x=>x.id===id)?.type))))errs.push(f.id+': choose numeric calculation inputs.');if(f.condition&&(!ids.has(f.condition.field)||f.condition.field===f.id||!f.condition.equals))errs.push(f.id+': invalid visibility rule.');if(f.columns&&(!f.columns.length||f.columns.some(c=>!c.id||!c.label)||new Set(f.columns.map(c=>c.id)).size!==f.columns.length))errs.push(f.id+': invalid grid column definition.');if(f.columns?.some(c=>c.type==='calculated'&&(!c.formula?.length||c.formula.some(id=>!f.columns.some(x=>x.id===id&&x.type==='number')))))errs.push(f.id+': calculated grid columns need numeric input columns.');if(f.mapping.some(id=>!findR(id)))errs.push(f.id+': unknown requirement ID.');}
 const visiting=new Set(),done=new Set();function visit(id){if(visiting.has(id)){errs.push('Cyclic field dependencies are not allowed.');return;}if(done.has(id))return;visiting.add(id);const f=def.fields.find(x=>x.id===id);for(const child of [...(f?.depends||[]),...(f?.condition?[f.condition.field]:[])])visit(child);visiting.delete(id);done.add(id);}for(const f of def.fields)visit(f.id);
 for(const {label,check} of faChecks(def)){if(!check.endpoint?.trim()||!check.path?.trim())errs.push(label+': configure a source reference and extraction.');if(['gt','gte','lt','lte'].includes(check.operator)&&(!String(check.threshold).trim()||!Number.isFinite(Number(check.threshold))))errs.push(label+': numeric threshold is required.');if(check.kind==='uptime'&&check.window==='Point in time')errs.push(label+': availability requires a reporting window.');if(check.type==='boolean'&&check.operator==='eq'&&!['true','false'].includes(String(check.threshold)))errs.push(label+': boolean expected value must be true or false.');}
 return [...new Set(errs)];
}
function faCreate(){openDialog('Create assessment form','One schema for human, integration and hybrid assessment instruments.',`<div class="stack">${input('name','Form name','','text','required maxlength="160"')}${select('mode','Start with',['Human','Integration','Hybrid'],'Human')}${area('description','Purpose and scope','','maxlength="1000"')}</div>`,'Create form',form=>{const x=values(form),f={id:uid('FORM'),name:x.name.trim(),mode:x.mode,framework:'',description:x.description.trim(),revision:1,status:'Draft',fields:[]};if(x.mode==='Human')f.fields=[faField('field1','Assessment owner','text')];else if(x.mode==='Integration')f.fields=[faField('field1','API capability','boolean',{mode:'integration',check:faCheck('api')})];else f.fields=[faField('field1','Assessment owner','text'),faField('field2','Service availability','percentage',{mode:'integration',check:faCheck('uptime')})];faInit().forms.unshift(f);audit('Created assessment form '+f.name,f.id);go('form-builder?form='+f.id);});}
function faSettings(id){const f=faInit().forms.find(x=>x.id===id);openDialog('Form settings','Framework seed linkage is a template relationship, not another requirement definition.',`<div class="stack">${input('name','Form name',f.name,'text','required maxlength="160"')}${area('description','Purpose and guidance',f.description)}${select('framework','Seed with framework',[['','No framework / custom form'],...FW.map(x=>[x.id,x.name])],f.framework)}</div>`,'Save settings',form=>{const x=values(form);f.name=x.name.trim();f.description=x.description.trim();f.framework=x.framework;faEdited(f);render();});}
function faAdd(){openDialog('Add a field','Choose the answer shape first; configure its source independently.',`<div class="fa-type-catalog">${Object.entries(FA_TYPES).map(([id,name])=>btn(name,'fa-add-type',`data-id="${id}"`,'small')).join('')}</div>`);}
function faColumns(id){const f=faForm(),q=f.fields.find(x=>x.id===id);openDialog('Mixed-grid columns','Typed column schema. Integration and calculated cells are read-only to respondents.',notice('Advanced demo editor: change labels, types, options, required, min/max, formula inputs, or add an integration check copied from a seeded column. The production UI should expose these as a column inspector.','mini')+area('columns','Column definitions (JSON)',JSON.stringify(q.columns,null,2),'required rows="20" spellcheck="false"')+`<p class="fa-subtle">Supported cell types: text, number, date, dropdown, multi, percentage, calculated. Use stable unique IDs. No executable expressions.</p>`,'Apply columns',form=>{let columns;try{columns=JSON.parse(values(form).columns);}catch{fail('Column JSON is invalid.');}requireValue(Array.isArray(columns)&&columns.length>0&&columns.length<=30,'Use between 1 and 30 columns.');for(const c of columns){requireValue(/^[A-Za-z][A-Za-z0-9_-]*$/.test(c.id||'')&&typeof c.label==='string'&&c.label.trim(),'Every column needs a stable ID and label.');requireValue(['text','number','date','dropdown','multi','percentage','calculated'].includes(c.type),'Unsupported column type.');if(['dropdown','multi'].includes(c.type))requireValue(Array.isArray(c.options)&&c.options.every(x=>typeof x==='string'),'Choice columns need string options.');if(c.mode==='integration')requireValue(c.check&&FA_CHECKS[c.check.kind],'Integration columns require a known check recipe.');}const candidate=clone(f);candidate.fields.find(x=>x.id===id).columns=columns;const errs=faDefinitionErrors(candidate);requireValue(!errs.length,errs.join(' '));q.columns=columns;f.mode=faActualMode(f);faEdited(f);render();},'');}
function faApplySettings(form){const f=faForm(),selected=faFieldSelected(f),q=clone(selected),x=values(form),tab=form.dataset.faSettings;
 if(tab==='field'){if(q.type!==x.type){const repl=faDefaultField(x.type,q.id),retained={label:q.label,help:q.help,mapping:q.mapping};for(const key of Object.keys(q))delete q[key];Object.assign(q,repl,retained);}q.label=x.label.trim();q.type=x.type;q.help=x.help.trim();q.required=x.required==='yes';if(x.options!==undefined)q.options=x.options.split('\n').map(s=>s.trim()).filter(Boolean);if(x.rows!==undefined)q.rows=x.rows.split('\n').map(s=>s.trim()).filter(Boolean);}
 if(tab==='source'){q.mode=x.mode;if(q.mode==='integration'){requireValue(!q.columns&&!['matrix','multi_matrix','attestation','evidence'].includes(q.type),'Configure source bindings on individual grid columns; this field shape cannot be a scalar technical result.');const changed=!q.check||q.check.kind!==x.checkKind;q.check=changed?faCheck(x.checkKind||'api'):q.check;if(!changed&&x.endpoint!==undefined){q.check.endpoint=x.endpoint.trim();q.check.path=x.path.trim();}q.type=q.check.type==='percentage'?'percentage':q.check.type==='boolean'?'boolean':q.check.type==='number'?'number':'text';}else if(q.mode==='calculated'){q.type='calculated';q.calcOp=x.calcOp||'sum';q.depends=(x.depends||'').split('\n').map(s=>s.trim()).filter(Boolean);}}
 if(tab==='rules'){q.mapping=(x.mapping||'').split('\n').map(s=>s.trim()).filter(Boolean);q.freshDays=bounded(x.freshDays,1,3650,'Freshness');q.condition=x.showWhen?{field:x.showWhen,equals:x.equals.trim()}:null;if(q.mode==='integration'){q.check.operator=x.operator;q.check.threshold=x.threshold;q.check.window=x.window;q.check.freshness=bounded(x.freshness,1,31536000,'Source freshness');q.check.minCoverage=Number(x.minCoverage);requireValue(Number.isFinite(q.check.minCoverage)&&q.check.minCoverage>=0&&q.check.minCoverage<=100,'Coverage must be 0–100%.');q.check.minSamples=bounded(x.minSamples,1,1000000,'Minimum samples');q.check.cadence=x.cadence;}}
 const candidate=clone(f);candidate.fields[candidate.fields.findIndex(a=>a.id===q.id)]=q;const errs=faDefinitionErrors(candidate);/* Draft calculated fields may need a second configuration pass. */
 requireValue(!errs.length||tab==='source'&&q.mode==='calculated'&&!q.depends.length,errs.join(' '));for(const key of Object.keys(selected))delete selected[key];Object.assign(selected,q);f.mode=faActualMode(f);faEdited(f);render();toast('Field configuration saved. Published assignments are unchanged.');
}
function faPublish(id){const f=faInit().forms.find(x=>x.id===id),errs=faDefinitionErrors(f);if(errs.length){openDialog('Form is not ready to publish','Resolve these definition issues.',`<div class="fa-errors">${errs.map(e).join('<br>')}</div>`);return;}openDialog('Publish a form version','This creates an immutable local definition snapshot, not a compliance decision.',`<h3>${e(f.name)}</h3><p>${f.fields.length} fields · ${faChecks(f).length} checks · ${faSlots(f).length} logical connection slots.</p>${notice('Existing assignments remain pinned to their prior version. New assignments can use this version. The demo does not implement production maker/checker approval or secure immutable storage.','mini')}`,'Publish version',()=>{const studio=faInit(),version=(faLatest(f)?.number||0)+1;f.revision=version;f.status='Published';f.mode=faActualMode(f);studio.versions.push({id:f.id+'@'+version,formId:f.id,number:version,definition:clone(f),published:new Date().toISOString()});audit('Published form '+f.id+' version '+version,f.id);render();toast('Version published. Attach it to a scoped program assessment.');},'');}
function faAttach(id,programId=''){const f=faInit().forms.find(x=>x.id===id),v=faLatest(f);requireValue(v,'Publish a version before attaching this form.');const slots=faSlots(v.definition),scopes=S.programs.flatMap(p=>p.targets.map(t=>[p.id+'::'+t,p.name+' / '+targetName(t)]));openDialog('Attach assessment form','Pin the published version to one program and exact assessment target.',`<h3>${e(v.definition.name)} ${pill('v'+v.number,'blue')}</h3><div class="stack">${select('scope','Program and target',scopes,programId?scopes.find(x=>x[0].startsWith(programId+'::'))?.[0]:scopes[0][0])}${slots.map(slot=>select('slot-'+slot,slot+' connection',[['','Unbound — configure later'],...FA_CONNECTORS.filter(c=>c.slot===slot).map(c=>[c.id,c.name])],'')).join('')}${notice('Connections shown are synthetic and use reference names, not real credentials. Unbound fields produce Unknown rather than silently using another target’s connection.','mini')}</div>`,'Attach published form',form=>{const x=values(form),[pid,target]=x.scope.split('::'),p=S.programs.find(z=>z.id===pid);requireValue(p?.targets.includes(target),'Target must belong to this program.');requireValue(!faInit().bindings.some(b=>b.programId===pid&&b.target===target&&b.formVersionId===v.id),'This form version is already attached to that target.');const b={id:uid('ASN'),formId:f.id,formVersionId:v.id,programId:pid,target,connections:Object.fromEntries(slots.map(slot=>[slot,x['slot-'+slot]||''])),created:new Date().toISOString()};faInit().bindings.push(b);audit('Attached '+v.id+' to '+targetName(target),pid);go('form-response?binding='+b.id);});}
function faEditBindings(id){const b=faInit().bindings.find(x=>x.id===id),slots=faSlots(faVersion(b.formVersionId).definition);openDialog('Bind technical data sources','Bindings belong to this assignment’s program and target.',`<p>${e(targetName(b.target))}</p><div class="stack">${slots.map(slot=>select('slot-'+slot,slot,[['','Unbound'],...FA_CONNECTORS.filter(c=>c.slot===slot).map(c=>[c.id,c.name])],b.connections[slot]||'')).join('')}${notice('Production bindings must be authorized for the tenant, legal entity, environment and assessed service. These selectors demonstrate configuration only.','mini')}</div>`,'Save bindings',form=>{const x=values(form);b.connections=Object.fromEntries(slots.map(slot=>[slot,x['slot-'+slot]||'']));audit('Updated demo form source bindings',b.programId);render();});}
function faExample(){const def=faDefinition(),res=faResponse();requireValue(res.status!=='Submitted','Submitted responses are locked.');for(const f of def.fields){if(f.mode!=='human')continue;if(f.columns){res.answers[f.id]=f.rows.map(row=>({...row,cells:Object.fromEntries(f.columns.filter(c=>c.mode!=='integration'&&c.type!=='calculated').map((c,ci)=>[c.id,c.type==='number'?2:c.type==='percentage'?98:c.type==='date'?'2026-11-30':c.type==='dropdown'?c.options[0]:c.type==='multi'?[c.options[0]]:ci===0?row.label:c.id==='evidence'?'SYNTHETIC-EV-01':c.id==='owner'?'Amina Bello':'Synthetic example']))}));}else if(f.type==='matrix')res.answers[f.id]=Object.fromEntries(f.rows.map((_,i)=>[i,f.options[0]]));else if(f.type==='multi_matrix')res.answers[f.id]=Object.fromEntries(f.rows.map((_,i)=>[i,[f.options[0],f.options[1]]]));else res.answers[f.id]=f.type==='attestation'?true:f.type==='boolean'?'Yes':f.type==='multi'?[f.options[0]]:['single','dropdown'].includes(f.type)?f.options[0]:f.type==='date'?'2026-11-13':['number','currency','percentage'].includes(f.type)?3:f.type==='evidence'?'SYNTHETIC-EV-ASSURANCE-01':'Synthetic demonstration response';}save();render();toast('Loaded explicitly synthetic human answers. Technical observations were not changed.');}
function faSubmit(){const res=faResponse(),def=faDefinition();requireValue(res.status!=='Submitted','Already submitted.');const errs=faErrors(def,res),checks=faChecks(def,res.answers),unknown=checks.filter(c=>!res.observations[c.key]||res.observations[c.key].result==='Unknown');if(unknown.length&&String(res.note||'').trim().length<12)errs.push('Explain the missing, stale or unknown technical checks (at least 12 characters).');if(errs.length){$('#fa-response-error').textContent=errs.slice(0,10).join(' ');return;}openDialog('Submit assessment snapshot','Failures and unknowns are retained for review; submission does not imply compliance.',select('respondent','Submitting respondent',CS_SEED.people,CS_SEED.people[0])+`<p class="mt16">${checks.length} technical fields · ${unknown.length} unresolved. The form version, answers and observations will be locked together.</p>`,'Submit snapshot',form=>{res.status='Submitted';res.submittedBy=values(form).respondent;res.submittedAt=new Date().toISOString();res.definitionSnapshot=clone(def);res.snapshot={answers:clone(res.answers),observations:clone(res.observations),note:res.note||'',runIds:clone(res.runIds)};audit('Submitted form assessment snapshot',faBinding()?.programId||def.id,res.submittedBy);render();toast('Submitted for review. Requirement evaluations are unchanged.');},'');}
function faRunDetail(id){const r=faInit().runs.find(x=>x.id===id),v=Object.values(r.results);openDialog(r.id,'Synthetic execution record · exact rule, source and scope are retained.',`<div class="fa-run-summary">${[['Collected',v.filter(x=>x.execution==='Succeeded').length],['Pass',v.filter(x=>x.result==='Pass').length],['Fail',v.filter(x=>x.result==='Fail').length],['Unknown',v.filter(x=>x.result==='Unknown').length]].map(([k,n])=>`<div><small>${k}</small><strong>${n}</strong></div>`).join('')}</div><p class="small mt16">${e(r.version)} · ${e(targetName(r.target))} · ${e(r.time)}</p>${v.map(o=>`<section class="source-block"><strong>${e(o.label)}</strong><div class="row wrap mt16">${faRunResult(o)}${pill(o.assurance)}<strong>${faValue(o.value)}</strong></div><div class="fa-ruleline">${e(o.rule)}</div><div class="fa-status-line"><span>Execution / quality</span><strong>${e(o.execution)} / ${e(o.quality)}</strong></div><div class="fa-status-line"><span>Coverage / samples</span><strong>${o.coverage}% · ${o.metrics?.valid??0}/${o.metrics?.expected??0}</strong></div><p class="fa-subtle mb0">${e(o.sourceReference)}<br>${e(o.reason)}</p></section>`).join('')}${btn('Export run JSON','fa-export-run',`data-id="${r.id}"`,'small mt16')}`,'',null,'');}
function faPaste(id){const q=faDefinition().fields.find(x=>x.id===id),res=faResponse();requireValue(res.status!=='Submitted','Submitted responses are locked.');const cols=q.columns.filter(c=>c.mode!=='integration'&&c.type!=='calculated');openDialog('Paste table rows','Tab-separated input. No header row. Source-backed and calculated cells cannot be imported.',`<p class="small">Column order: ${cols.map(c=>e(c.label)).join(' → ')}. Multiple selections use | separators.</p>${area('table','Rows','','required rows="10"')}`,'Replace grid rows',form=>{const lines=values(form).table.trim().split(/\r?\n/);requireValue(lines.length>0&&lines.length<=100,'Paste 1–100 rows.');const rows=lines.map((line,i)=>{const values=line.split('\t');requireValue(values.length===cols.length,`Row ${i+1}: expected ${cols.length} cells.`);const cells={};cols.forEach((c,j)=>{const s=values[j].trim();if(['number','percentage'].includes(c.type)){requireValue(s!==''&&Number.isFinite(Number(s)),`Row ${i+1}: ${c.label} needs a number.`);requireValue(Number(s)>=(c.min??-Infinity)&&Number(s)<=(c.max??Infinity),`${c.label} is outside its allowed range.`);cells[c.id]=Number(s);}else if(c.type==='multi'){cells[c.id]=s.split('|').map(x=>x.trim()).filter(Boolean);requireValue(cells[c.id].every(v=>c.options.includes(v)),'Unknown multi-choice option.');}else{if(c.type==='dropdown')requireValue(c.options.includes(s),'Unknown dropdown option.');if(c.type==='date')validDate(s,'Cell date',false);cells[c.id]=s;}});return {id:uid('row'),label:values[0]||'Row '+(i+1),cells};});res.answers[q.id]=rows;save();render();});}
Object.assign(actions,{
 'fa-create':faCreate,'fa-settings':el=>faSettings(el.dataset.id),'fa-add':faAdd,
 'fa-add-type':el=>{const f=faForm(),q=faDefaultField(el.dataset.id,uid('field'));f.fields.push(q);faEdited(f);closeDialog();go(`form-builder?form=${f.id}&field=${q.id}`);},
 'fa-select':el=>{go(`form-builder?form=${faForm().id}&field=${el.dataset.id}&inspector=${current.params.get('inspector')||'field'}`);},
 'fa-inspector':el=>go(`form-builder?form=${faForm().id}&field=${faFieldSelected(faForm()).id}&inspector=${el.dataset.id}`),
 'fa-columns':el=>faColumns(el.dataset.id),
 'fa-move':el=>{const f=faForm(),i=f.fields.findIndex(x=>x.id===el.dataset.id),j=i+Number(el.dataset.direction);if(j<0||j>=f.fields.length)return;[f.fields[i],f.fields[j]]=[f.fields[j],f.fields[i]];faEdited(f);render();},
 'fa-remove':el=>{const f=faForm(),id=el.dataset.id;requireValue(!f.fields.some(x=>x.condition?.field===id||x.depends?.includes(id)),'Remove dependent conditions or calculations before deleting this field.');f.fields=f.fields.filter(x=>x.id!==id);faEdited(f);render();},
 'fa-publish':el=>faPublish(el.dataset.id),'fa-attach':el=>faAttach(el.dataset.id,el.dataset.program||''),'fa-bind':el=>faEditBindings(el.dataset.id),
 'fa-export':el=>download('clearsight-form-schema.json',JSON.stringify({demonstrationOnly:true,definition:faInit().forms.find(x=>x.id===el.dataset.id)},null,2)),
 'fa-run':faRun,'fa-run-detail':el=>faRunDetail(el.dataset.id),'fa-export-run':el=>download('clearsight-form-check-run.json',JSON.stringify({demonstrationOnly:true,run:faInit().runs.find(x=>x.id===el.dataset.id)},null,2)),
 'fa-example':faExample,'fa-submit':faSubmit,'fa-paste':el=>faPaste(el.dataset.id),
 'fa-add-row':el=>{const r=faResponse(),q=faDefinition().fields.find(x=>x.id===el.dataset.id);requireValue(r.status!=='Submitted','Submitted responses are locked.');r.answers[q.id]??=q.rows.map(x=>({...x,cells:{}}));requireValue(r.answers[q.id].length<100,'The prototype supports up to 100 rows per table.');r.answers[q.id].push({id:uid('row'),label:'New row',cells:{}});save();render();},
 'fa-remove-row':el=>{const r=faResponse(),q=faDefinition().fields.find(x=>x.id===el.dataset.id);requireValue(r.status!=='Submitted','Submitted responses are locked.');r.answers[q.id]??=q.rows.map(x=>({...x,cells:{}}));if(r.answers[q.id].length>1){const removed=r.answers[q.id].pop();for(const key of Object.keys(r.observations))if(key.startsWith(q.id+'::'+removed.id+'::'))delete r.observations[key];}save();render();}
});
document.addEventListener('submit',ev=>{if(ev.target.id!=='fa-field-settings')return;ev.preventDefault();try{faApplySettings(ev.target);}catch(err){$('.fa-form-error',ev.target).textContent=err.message;}});
document.addEventListener('change',ev=>{const el=ev.target;if(!el.matches('[data-fa-answer],[data-fa-cell],[data-fa-matrix],[data-fa-seed]'))return;try{
 if(el.matches('[data-fa-seed]')){const d=draft();d.formTemplates??=faInit().forms.filter(f=>f.framework===d.frameworkId).map(f=>f.id);d.formTemplates=el.checked?[...new Set([...d.formTemplates,el.dataset.faSeed])]:d.formTemplates.filter(id=>id!==el.dataset.faSeed);save();return;}
 const def=faDefinition(),res=faResponse();if(res.status==='Submitted')return;
 if(el.dataset.faAnswer){const f=def.fields.find(x=>x.id===el.dataset.faAnswer);res.answers[f.id]=f.type==='multi'?$$(`[data-fa-answer="${f.id}"]:checked`).map(x=>x.value):f.type==='attestation'?el.checked:['number','percentage','currency'].includes(f.type)?el.value===''?'':Number(el.value):el.value;}
 if(el.dataset.faMatrix){const f=def.fields.find(x=>x.id===el.dataset.faMatrix);res.answers[f.id]??={};res.answers[f.id][el.dataset.row]=f.type==='matrix'?el.value:$$(`[data-fa-matrix="${f.id}"][data-row="${el.dataset.row}"]:checked`).map(x=>x.value);}
 if(el.dataset.faCell){const q=def.fields.find(x=>x.id===el.dataset.faCell);res.answers[q.id]??=q.rows.map(r=>({...r,cells:{}}));const row=res.answers[q.id].find(x=>x.id===el.dataset.row),col=q.columns.find(c=>c.id===el.dataset.col);requireValue(col.mode!=='integration'&&col.type!=='calculated','Source-backed and calculated cells cannot be edited.');row.cells??={};row.cells[col.id]=col.type==='multi'?[...el.selectedOptions].map(x=>x.value):['number','percentage'].includes(col.type)?el.value===''?'':Number(el.value):el.value;}
 save();const oldY=scrollY;render();window.scrollTo(0,oldY);
 }catch(err){toast(err.message);}});
document.addEventListener('input',ev=>{if(ev.target.matches('[data-fa-note]')){faResponse().note=ev.target.value;save();}});
/* Composes, rather than replaces, existing adoption and program workflows. */
const faOldAdoptView=adoptView;
adoptView=function(){const html=faOldAdoptView(),d=draft(),templates=faInit().forms.filter(f=>f.framework===d.frameworkId);d.formTemplates??=templates.map(f=>f.id);return html+panel('Assessment forms included in this seed','Select reusable instruments to assign when this program is published. Integration connections remain unbound until configured.',templates.length?templates.map(f=>`<div class="fa-template-strip"><label class="checkbox-row grow"><input type="checkbox" data-fa-seed="${f.id}" ${d.formTemplates.includes(f.id)?'checked':''}><span>${e(f.name)}<small class="muted"> · ${e(f.mode)} · ${f.fields.length} fields</small></span></label>${link('Inspect form',`form-builder?form=${f.id}`,'small')}</div>`).join(''):empty('No additional forms seeded','The existing requirement questions remain available.'));};
const faOldPublishReview=publishReview;
publishReview=function(){faOldPublishReview();if(!modalSave||!S.draft)return;const d=S.draft,selected=[...(d.formTemplates||[])],oldSave=modalSave;modalSave=function(form){const result=oldSave(form);if(result===false)return false;const p=S.programs[0];for(const id of selected){const f=faInit().forms.find(x=>x.id===id),v=faLatest(f);if(!v)continue;for(const target of p.targets)faInit().bindings.push({id:uid('ASN'),formId:f.id,formVersionId:v.id,programId:p.id,target,connections:Object.fromEntries(faSlots(v.definition).map(slot=>[slot,''])),created:new Date().toISOString()});}save();return result;};};
/* The action map captures function references, so update the publish entry explicitly. */
actions['publish-review']=publishReview;
const faOldProgramView=programView;
programView=function(){const html=faOldProgramView(),p=prog(),t=selectedTarget(p);if(current.params.get('tab')!=='assessments')return html;const bs=faInit().bindings.filter(b=>b.programId===p.id&&b.target===t);return html+`<div class="mt16">`+panel('Additional assessment forms','Pinned instruments for this target. Responses and automated checks do not replace requirement review.',bs.length?table(['Form','Version','Source bindings','Response',''],bs.map(b=>{const v=faVersion(b.formVersionId);return {cells:[`<strong>${e(v.definition.name)}</strong><small>${e(v.definition.mode)}</small>`,e(v.id),`${Object.values(b.connections).filter(Boolean).length}/${faSlots(v.definition).length} ${faSlots(v.definition).length?btn('Configure','fa-bind',`data-id="${b.id}"`,'quiet small'):''}`,pill(faInit().responses[b.id]?.status||'Draft'),link('Open',`form-response?binding=${b.id}`,'small')]};})):empty('No additional form assigned','Use the form library to attach a published form.',link('Open forms','forms','small')))+`</div>`;};
/* Pinned definitions also apply after submit in an unassigned designer preview. */
const faOldDefinition=faDefinition;
faDefinition=function(){const res=faInit().responses[faResponseKey()];return res?.status==='Submitted'&&res.definitionSnapshot?res.definitionSnapshot:faOldDefinition();};
Object.assign(titles,{'form-builder':'Form builder','form-response':'Assessment form','check-runs':'Technical check history'});
faInit();
window.CLEAR_SIGHT_FORMS=Object.freeze({version:'2.2-demo',getState:()=>clone(faInit()),evaluate:(c,r,now)=>faEvaluate(c,r,now),getRecipes:()=>clone(FA_CHECKS),compare:faCompare,definitionErrors:faDefinitionErrors,calculate:faCalc});
/* Visual typed-column editor; staged changes apply atomically to the form draft. */
let faColumnDraft=null;
function faColumnCapture(){if(!faColumnDraft||!$('#modal-form'))return;const data=values($('#modal-form'));faColumnDraft.columns=faColumnDraft.columns.map((old,i)=>{const x={...old,label:data['c'+i+'label']??old.label,type:data['c'+i+'type']||old.type};x.required=data['c'+i+'required']==='yes';x.mode=data['c'+i+'mode']||'human';if(['dropdown','multi'].includes(x.type))x.options=(data['c'+i+'options']??(old.options||[]).join(' | ')).split('|').map(s=>s.trim()).filter(Boolean);if(x.type==='calculated'||x.mode==='calculated'){x.type='calculated';x.mode='calculated';x.formula=(data['c'+i+'formula']??(old.formula||[]).join(',')).split(',').map(s=>s.trim()).filter(Boolean);}if(x.type==='number'){x.min=data['c'+i+'min']===''?undefined:Number(data['c'+i+'min']??old.min??0);x.max=data['c'+i+'max']===''?undefined:Number(data['c'+i+'max']??old.max??1000000);}if(x.mode==='integration'){const kind=data['c'+i+'kind']||old.check?.kind||'uptime';x.check=old.check?.kind===kind?{...old.check}:faCheck(kind);if(old.check?.kind===kind){x.check.operator=data['c'+i+'operator']||x.check.operator;x.check.threshold=data['c'+i+'threshold']??x.check.threshold;}x.type=x.check.type==='percentage'?'percentage':x.check.type==='number'?'number':'text';}return x;});}
function faColumnDialog(){const d=faColumnDraft;openDialog('Configure grid columns','Each column has its own type, input source and validation rules.',`<div class="fa-stack">${d.columns.map((c,i)=>`<section class="source-block"><div class="row between mb16"><strong class="mono">${e(c.id)}</strong>${btn('Remove','fa-column-remove',`data-id="${i}"`,'quiet small danger')}</div><div class="grid2">${input('c'+i+'label','Column heading',c.label,'text','required maxlength="100"')}${select('c'+i+'type','Cell type',[['text','Text'],['number','Number'],['date','Date'],['dropdown','Dropdown'],['multi','Multiple choice'],['percentage','Percentage'],['calculated','Calculated']],c.type,'data-fa-column-change')}${select('c'+i+'mode','Value source',[['human','Respondent'],['integration','Integration'],['calculated','Calculated']],c.mode||'human','data-fa-column-change')}${select('c'+i+'required','Required cells',[['yes','Required'],['no','Optional']],c.required===false?'no':'yes')}</div>${['dropdown','multi'].includes(c.type)?input('c'+i+'options','Choices separated by |',(c.options||[]).join(' | '),'text','required'):''}${c.type==='number'&&c.mode!=='integration'?`<div class="grid2 mt16">${input('c'+i+'min','Minimum',c.min??'','number')}${input('c'+i+'max','Maximum',c.max??'','number')}</div>`:''}${c.type==='calculated'||c.mode==='calculated'?input('c'+i+'formula','Multiply these numeric column IDs (comma separated)',(c.formula||[]).join(', '),'text','required'):''}${c.mode==='integration'?`<div class="stack mt16">${select('c'+i+'kind','Check recipe',Object.entries(FA_CHECKS).map(([k,x])=>[k,x.label]),c.check?.kind||'uptime','data-fa-column-change')}${select('c'+i+'operator','Rule',[['gt','Greater than'],['gte','At least'],['lt','Less than'],['lte','At most'],['eq','Equals']],c.check.operator)}${input('c'+i+'threshold','Threshold / expected',c.check.threshold,'text','required')}<p class="fa-subtle mb0">${e(c.check.slot)} · ${e(c.check.window)} · ${e(c.check.claim)}</p></div>`:''}</section>`).join('')}</div><div class="mt16">${btn(icon('plus')+' Add column','fa-column-add','','small')}</div>${notice('Grid source observations retain the stable row ID and column ID. Mixed-cell source overrides and row-asset binding administration require the production backend.','mini mt16')}`,'Apply columns',()=>{faColumnCapture();const f=faForm(),candidate=clone(f);candidate.fields.find(x=>x.id===d.fieldId).columns=clone(d.columns);for(const c of d.columns){requireValue(c.label.trim(),'Each column needs a heading.');if(['dropdown','multi'].includes(c.type))requireValue(c.options.length>0,'Choice columns need at least one choice.');if(c.mode==='calculated'){c.type='calculated';candidate.fields.find(x=>x.id===d.fieldId).columns.find(x=>x.id===c.id).type='calculated';}}const errors=faDefinitionErrors(candidate);requireValue(!errors.length,errors.join(' '));f.fields.find(x=>x.id===d.fieldId).columns=clone(d.columns);f.mode=faActualMode(f);faEdited(f);faColumnDraft=null;render();},'');}
faColumns=function(id){faColumnDraft={fieldId:id,columns:clone(faForm().fields.find(x=>x.id===id).columns)};faColumnDialog();};
actions['fa-column-add']=()=>{faColumnCapture();requireValue(faColumnDraft.columns.length<30,'The demo supports up to 30 columns.');faColumnDraft.columns.push({id:uid('col'),label:'New column',type:'text',mode:'human',required:false});faColumnDialog();};
actions['fa-column-remove']=el=>{faColumnCapture();requireValue(faColumnDraft.columns.length>1,'Keep at least one column.');const index=Number(el.dataset.id),id=faColumnDraft.columns[index].id;requireValue(!faColumnDraft.columns.some(c=>c.formula?.includes(id)),'Remove calculated-column dependencies first.');faColumnDraft.columns.splice(index,1);faColumnDialog();};
document.addEventListener('change',ev=>{if(ev.target.matches('[data-fa-column-change]')){faColumnCapture();faColumnDialog();}});
